// Realistic ElevenLabs post-call webhook payload (post_call_transcription)
var body = {
  type: "post_call_transcription",
  event_timestamp: Math.floor(Date.now()/1000),
  data: {
    agent_id: "agent_3701kvdy0a45eywvg4yn9kw8pqv6",
    conversation_id: "test-conv-001",
    status: "done",
    transcript: [
      { role: "agent", message: "Hallo, hier ist Unica. Welche Versicherung moechten Sie?" },
      { role: "user", message: "Eine Kfz-Versicherung, Vollkasko." },
      { role: "agent", message: "Wie alt ist der Hauptlenker?" },
      { role: "user", message: "42 Jahre, 110 kW, Wien, Fahrzeugwert 25000 Euro, 8 schadenfreie Jahre, ein Lenker." },
      { role: "agent", message: "Die genaue Vorab-Praemie liegt bei circa 1260 Euro pro Jahr fuer Kfz-Vollkasko." },
      { role: "user", message: "Max Mustermann, 0660 1234567." }
    ],
    metadata: { call_duration_secs: 95, phone_call: null },
    analysis: {
      transcript_summary: "Kunde wuenscht Kfz-Vollkasko fuer 42-jaehrigen Lenker in Wien, 110 kW, Wert 25000 Euro, 8 schadenfreie Jahre. Vorab-Praemie ca. 1260 Euro pro Jahr. Kontakt: Max Mustermann, 0660 1234567.",
      call_successful: "success",
      data_collection_results: {
        full_name: { value: "Max Mustermann" },
        mobile_phone: { value: "06601234567" },
        email: { value: null },
        postal_code: { value: null },
        date_of_birth: { value: null },
        preferred_language: { value: "German" },
        line_of_business: { value: "car" },
        lead_intent: { value: "New" },
        indicative_quote: { value: "1260 Euro pro Jahr fuer Kfz-Vollkasko" },
        line_specific_details: { value: "Vollkasko, 42 J., 110 kW, Wien, 25000 Euro, 8 sf, 1 Lenker" },
        current_carrier: { value: null },
        current_premium: { value: null },
        budget: { value: null },
        effective_date: { value: null },
        prior_claims: { value: "0" },
        prior_lapse: { value: null },
        consent_tcpa: { value: true },
        consent_recording: { value: null },
        conversation_summary: { value: "Kfz-Vollkasko Lead, Max Mustermann" }
      }
    }
  }
};
return [{ json: { body: body } }];

var b = $json.body || $json;
var d = b.data || b;
var dc = (d.analysis && d.analysis.data_collection_results) || {};
function v(k){ return (dc[k] && dc[k].value!==undefined) ? dc[k].value : null; }
var tr = d.transcript || [];
var full = tr.map(function(t){ return (t.role||"")+": "+(t.message||""); }).join("\n");
var convId = d.conversation_id || ("CONV-"+Date.now());
var CASE_TYPE_ID = "OOPP-InsConv-Work-Lead";
var content = {
  SourceChannel: (d.metadata && d.metadata.phone_call) ? "Phone" : "WebVoice",
  ExternalConversationID: convId,
  LineOfBusiness: v("line_of_business"),
  LeadIntent: v("lead_intent"),
  QualificationMode: "LLM",
  IndicativeQuote: v("indicative_quote"),
  ConversationSummary: (d.analysis && d.analysis.transcript_summary) || v("conversation_summary"),
  Customer: { FullName: v("full_name"), MobilePhone: v("mobile_phone"), Email: v("email"), PostalCode: v("postal_code"), DateOfBirth: v("date_of_birth"), PreferredLanguage: v("preferred_language") },
  CoverageRequest: { LineSpecificDetails: v("line_specific_details"), CurrentCarrier: v("current_carrier"), CurrentPremium: v("current_premium"), Budget: v("budget"), EffectiveDate: v("effective_date"), PriorClaims: v("prior_claims"), PriorLapse: v("prior_lapse") },
  Consents: [ { ConsentType:"TCPA", Granted: !!v("consent_tcpa"), Timestamp: new Date().toISOString() }, { ConsentType:"Recording", Granted: !!v("consent_recording"), Timestamp: new Date().toISOString() } ],
  Transcript: { FullText: full, SlotMapJSON: JSON.stringify(dc), DurationSec: (d.metadata && d.metadata.call_duration_secs)||null, ModelVersion: d.agent_id||null }
};
var pega_body = { caseTypeID: CASE_TYPE_ID, processID: "pyStartCase", content: content };
return [{ json: { conversation_id: convId, pega_body: pega_body } }];

var r = $json;
var sent = $('Map to Pega').first().json.pega_body;
return [{ json: { pega_status: (r.statusCode!==undefined? r.statusCode : null), pega_response: (r.body!==undefined? r.body : r), sent_to_pega: sent } }];
